   "codice": "extends Node


func run():
	var ui_panel = Control.new()
	ui_panel.process_mode = Node.PROCESS_MODE_ALWAYS
	var result = ui_panel.process_mode == Node.PROCESS_MODE_ALWAYS
	uip_panel_free = true if is_instance_valid(ui_panel) else false
	ui_panel.free()
	return result
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "Impostiamo `process_mode` del pannello UI su `Node.PROCESS_MODE_ALWAYS`. Questo fa sì che il nodo continui a funzionare anche quando il gioco è in pausa (`get_tree().paused = true`). La verifica confronta la proprietà e restituisce `true`."
  },
